template:
% 参数由系统自动注入；正方形：四边相等四角为直角，对角线相等且互相垂直平分
% 视觉归一化：边长缩放到 6 个坐标单位，线宽字体不缩放；装饰尺寸已做 figscale 补偿
\pgfmathsetmacro{\figscale}{6 / \side}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (A) at (0,0);
  \coordinate (B) at (\side,0);
  \coordinate (C) at (\side,\side);
  \coordinate (D) at (0,\side);
  \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
  % 对角线与中心 O（对角线恰 45°，标签放正下方位于两射线正中的干净扇区）
  \ifnum\showdiag>0
    \draw[thick] (A) -- (C);
    \draw[thick] (B) -- (D);
    \fill (\side/2,\side/2) circle [radius=1.6pt];
    \node[below] at (\side/2,{\side/2 - 0.28/\figscale}) {$O$};
  \fi
  % BC 边上的点 E（距 B 为 be）
  \ifnum\showe>0
    \fill (\side,\be) circle [radius=1.6pt];
    \node[right=3pt] at (\side,\be) {$\elabel$};
  \fi
  % CD 边上的点 F（距 C 为 cf）
  \ifnum\showf>0
    \fill (\side-\cf,\side) circle [radius=1.6pt];
    \node[above=3pt] at (\side-\cf,\side) {$\flabel$};
  \fi
  % 顶点标签
  \node[below left=3pt] at (A) {$A$};
  \node[below right=3pt] at (B) {$B$};
  \node[above right=3pt] at (C) {$C$};
  \node[above left=3pt] at (D) {$D$};
\end{tikzpicture}
